import { log } from "./shared/deep";
import { alpha } from "./lib-a/alpha";

log("index entry loaded", alpha);

// SPA: 唯一的 HTML 入口只直接引用 index/runtime/shared 等入口分块，
// 下面的 "路由" 全部动态加载。dj 的输入就是这一张首页。

// named async chunk
import(/* webpackChunkName: "views-home" */ "./views/home.js").then((m) =>
  m.render()
);

// prefetch: runtime injects <link rel="prefetch"> when chunk demanded
import(/* webpackChunkName: "views-about", webpackPrefetch: true */ "./views/about.js");

// preload flag on the same home chunk (merged, adds preload behavior)
import(/* webpackChunkName: "views-home", webpackPreload: true */ "./views/home.js");

// lazy-once: single chunk, one-time flag (webpack only)
import(/* webpackChunkName: "views-settings", webpackMode: "lazy-once" */ "./views/settings.js");
import(/* webpackChunkName: "views-settings", webpackMode: "lazy-once" */ "./views/settings.js");

// 嵌套链：team -> dashboard -> metrics（三层嵌套）
import(/* webpackChunkName: "views-team" */ "./views/team.js").then((m) =>
  m.render()
);

// 懒模块
import(/* webpackChunkName: "page2-extra" */ "./page2-extra.js").then((m) =>
  m.side()
);

// runtime "expression" imports: parcel cannot statically analyze
// template-literal import() specs, so each context file gets its own
// static import() call inside a runtime branch (same chunk set).
window.loadTemplate = (name) => {
  if (name === "a") return import("./templates/a.js");
  if (name === "b") return import("./templates/b.js");
  if (name === "c") return import("./templates/c.js");
  return Promise.reject(new Error("unknown template: " + name));
};

window.loadWidget = (name) => {
  if (name === "x") return import("./widgets/x.js");
  if (name === "y") return import("./widgets/y.js");
  return Promise.reject(new Error("unknown widget: " + name));
};

// web worker -> separate worker chunk (parcel needs module-type marker when
// the worker file itself contains imports)
window.worker = new Worker(new URL("./worker.js", import.meta.url), {
  type: "module",
});